const t=[{target:"#local-produce",title:"Welcome to Local Produce",icon:"fal fa-apple-alt",color:"#4caf50",content:"Local Produce turns your computer into a sovereign data node. Instead of big tech corporations taking your data for free, you own your data, package it into sovereign crates, and earn tokens when people lease it.",placement:"right"},{target:"#local-produce-nav",title:"Sovereign Navigation Drawer",icon:"fal fa-bars",color:"#4caf50",content:"Use the side drawer to easily navigate across your entire data economy: Overview, Market Stand, Apple Carts, Farmer's Market, and the Coin Splitter.",placement:"right"},{target:"#nav-item-carts",title:"Apple Carts & Harvest Pipelines",icon:"fal fa-shopping-basket",color:"#4caf50",content:"Apple Carts automatically discovers data created by your apps (like Solitaire stats, telemetry, and notes). Toggle harvesting on to sanitize PII and earn daily $DIRT rewards.",placement:"right",onEnter:()=>{const e=document.querySelector("#nav-item-carts");e&&e.click()}},{target:"#nav-item-splits",title:"Coin Splitter & 3-Way Routing",icon:"fal fa-chart-pie",color:"#ffd54f",content:"Every time someone leases your data, smart contracts divide the payment. You choose your cut (up to 99.8%), while a guaranteed 0.10% floor fuels the community DAO and protocol builders.",placement:"right",onEnter:()=>{const e=document.querySelector("#nav-item-splits");e&&e.click()}},{target:"#nav-item-market",title:"The Federated Farmer's Market",icon:"fal fa-store",color:"#62c9ff",content:"Explore data crates and live telemetry streams shared by other sovereign nodes across the w4 network. Check Web-of-Trust trust scores and dock one-click leases.",placement:"right",onEnter:()=>{const e=document.querySelector("#nav-item-market");e&&e.click()}},{target:"#nav-item-stand",title:"Market Stand & Storage Weights",icon:"fal fa-balance-scale",color:"#a855f7",content:"Inspect your local device storage footprint with dynamic visual tree-maps. You can export raw records or compost items to mathematically erase encryption keys.",placement:"right",onEnter:()=>{const e=document.querySelector("#nav-item-stand");e&&e.click()}},{target:()=>null,title:"You Are in Full Control",icon:"fal fa-shield-check",color:"#4caf50",content:"Your data stays on your device inside your encrypted BlackBOX until you decide to package and mint it onto the Elysium blockchain. Happy harvesting!"}];export{t as localProduceTourSteps};
